message.content:
{
  "ledger": {
    "p78:e605": {
      "state": "represented",
      "fact_ids": [],
      "note": "섹션 제목('2. CUDA 공식 가이드에 적힌 숨은 진실'). 승인된 사실에 별도 보존되지 않았으나, 제목 자체는 연구 내용이라기보다 구조 표식이므로 미보존 허용."
    },
    "p78:e606": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "NVIDIA CUDA 가이드 인용을 도입하는 도입 문장. 인용문(p78:e607)과 함께 보존돼야 할 맥락이나 승인된 사실에 없음."
    },
    "p78:e607": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "NVIDIA CUDA 프로그래밍 가이드의 직접 인용문('호스트 메모리가 Pageable일 때 cudaMemcpyAsync는 비동기가 아니라...'). 외부 권위 출처의 직접 인용으로 핵심 근거임에도 승인된 사실에 보존되지 않음."
    },
    "p78:e608": {
      "state": "represented",
      "fact_ids": ["P0078F0013"],
      "note": "No-Pin 시 CPU L1 캐시 복사 및 드라이버 스테이징 버퍼 동작 설명. P0078F0013으로 보존됨."
    },
    "p78:e609": {
      "state": "represented",
      "fact_ids": [],
      "note": "섹션 제목('3. Pinned Memory는 언제 빛을 발하는가?'). 구조 표식으로 미보존 허용."
    },
    "p78:e610": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'데이터가 수 MB ~ 수백 MB일 때'라는 Pinned Memory 유효 조건 제시. p78:e611과 연결된 조건이나 승인된 사실에 없음."
    },
    "p78:e611": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "구체적 수치 포함: 'DMA의 고속 대역폭(1224GB/s)', 'Pinned Memory가 일반 메모리보다 23배 빠릅니다'. 승인된 사실에 이 측정값이 보존되지 않음."
    },
    "p78:e612": {
      "state": "represented",
      "fact_ids": [],
      "note": "섹션 소제목('우리 데이터처럼 1 KB일 때:'). 구조 표식으로 미보존 허용."
    },
    "p78:e613": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'대역폭은 아무 의미가 없고 셋업 지연시간(Latency)이 지배합니다'라는 해석 문장. 승인된 사실에 없음."
    },
    "p78:e614": {
      "state": "represented",
      "fact_ids": [],
      "note": "섹션 제목('4. 그럼 Pinned Memory를 왜 쓸까요? (이 연구의 핵심 가치)'). 구조 표식으로 미보존 허용."
    },
    "p78:e615": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'평균 속도에서는 No-Pin이 13초 빨랐지만'이라는 구체적 수치(13초) 포함. 승인된 사실에 이 수치가 보존되지 않음."
    },
    "p78:e616": {
      "state": "represented",
      "fact_ids": [],
      "note": "비교 표(No-Pin vs Pinned Memory). structured_table_manifest에 table_id='p78:e616#table-1', complete=true로 등록됨. 행 3개, 머리글 3열 모두 보존 확인."
    },
    "p78:e617": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "표의 상세 해설 목록. '최대 11.6ms', '1.64ms', '1~2 μs' 등 구체적 수치와 OS 페이징 차단 메커니즘 설명이 포함되나 승인된 사실에 보존되지 않음. 표(p78:e616)와 중복되는 수치가 있으나 목록 형태의 서술은 별도 보존 필요."
    },
    "p78:e618": {
      "state": "represented",
      "fact_ids": [],
      "note": "섹션 제목('논문/보고서에 쓸 수 있는 최고의 결론'). 구조 표식으로 미보존 허용."
    },
    "p78:e619": {
      "state": "represented",
      "fact_ids": ["P0078F0009"],
      "note": "논문/보고서용 결론 문단. P0078F0009로 보존됨. 1.4%, 11.6ms, 1.64ms, 60% 이상 안정화 등 측정값 포함."
    },
    "p78:e620": {
      "state": "represented",
      "fact_ids": ["P0078F0010"],
      "note": "AI 조언(평가) 문단. P0078F0010으로 보존됨."
    }
  }
}
